func (v videoPointDo) FindInBatch(batchSize int, fc func(tx gen.Dao, batch int) error) (results []*model.VideoPoint, err error) {
	buf := make([]*model.VideoPoint, 0, batchSize)
	err = v.DO.FindInBatches(&buf, batchSize, func(tx gen.Dao, batch int) error {
		defer func() { results = append(results, buf...) }()
		return fc(tx, batch)
	})
	return results, err
}

